// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;
    function setUp() public {
        c = new RoundFactory();
        c.initialize();
    }
    function testFuzz_property(address proposed) public {
        // establish a known nonzero implementation first (this contract is the owner)
        vm.startPrank(address(this));
        c.updateRoundImplementation(payable(address(0x1)));
        // proposed is fully fuzzed: zero included — zero is exactly the bug-triggering input
        try c.updateRoundImplementation(payable(proposed)) {
            // succeeded: reference only succeeds when proposed != 0, so stored value is nonzero
        } catch {
            // reverted: reference reverts on zero; stored value must remain the prior nonzero one
        }
        vm.stopPrank();
        assertTrue(c.roundImplementation() != address(0), "roundImplementation must never be zero");
    }
}
